"""Recursive merge for layered configuration mappings."""
from collections.abc import Mapping
from copy import deepcopy


def deep_merge(layers):
    result = {}
    for layer in layers:
        if not isinstance(layer, Mapping):
            raise TypeError("each layer must be a mapping")
        for key, value in layer.items():
            if not isinstance(key, str):
                raise TypeError("configuration keys must be strings")
            if value is None:
                result.pop(key, None)
            elif isinstance(value, Mapping):
                previous = result.get(key)
                base = previous if isinstance(previous, Mapping) else {}
                result[key] = deep_merge([base, value])
            else:
                result[key] = deepcopy(value)
    return result

