"""Environment interpolation for nested configuration values."""
import re

_TOKEN = re.compile(r"([A-Za-z_][A-Za-z0-9_]*)(?::-(.*))?")


def _resolve_string(text, env):
    output = []
    index = 0
    while index < len(text):
        escaped = text.startswith("$${", index)
        ordinary = text.startswith("${", index)
        if not escaped and not ordinary:
            output.append(text[index])
            index += 1
            continue
        start = index + (3 if escaped else 2)
        end = text.find("}", start)
        if end < 0:
            output.append(text[index:])
            break
        whole = text[index:end + 1]
        if escaped:
            output.append(whole[1:])
            index = end + 1
            continue
        match = _TOKEN.fullmatch(text[start:end])
        if not match:
            output.append(whole)
            index = end + 1
            continue
        name, default = match.groups()
        present = name in env
        current = str(env[name]) if present else None
        if present and current != "":
            output.append(current)
        elif default is not None:
            output.append(default)
        elif present:
            output.append("")
        else:
            raise KeyError(name)
        index = end + 1
    return "".join(output)


def resolve(value, env):
    if isinstance(value, str):
        return _resolve_string(value, env)
    if isinstance(value, list):
        return [resolve(item, env) for item in value]
    if isinstance(value, dict):
        return {key: resolve(item, env) for key, item in value.items()}
    return value
